-- V3_2 (T05, date reale): obiectivele, agrementul și gastronomia din județul Arad, din exportul visitarad.ro
-- făcut pentru Hack4Arad (https://baditaflorin.github.io/hack4arad-turism-arad/, colectat 2026-11-03).
-- Atribuire obligatorie: „Date: CNIPT Arad / visitarad.ro” (în image_credit) + source_url pe fiecare rând.
-- CNIPT (3 nov 2026): informațiile de pe site sunt publice și pot fi preluate; fără licență formală — pozele rămân ale CNIPT,
-- le legăm direct de pe visitarad.ro (nu le copiem în repo). Detalii și limitări: AradEx-Plan/docs/ARAD-DATA.md.
--
-- 1) coloana source_url (fișa sursă);
-- 2) corecții la cele 12 obiective din V3_1: coordonatele verificate pe OpenStreetMap + visitarad (erau deplasate
--    150 m – 4 km), o frază greșită din ghid (Parcul Reconcilierii nu e în spatele Primăriei) și poza pentru Podgoria Miniș.
--    Fiecare UPDATE se aplică doar dacă rândul are încă valoarea din seed (nu suprascrie editările Primăriei);
-- 3) 223 locuri noi (fără cazare: nu avem tip pentru ea; 23 fișe dublate pe site au fost unite). Id-urile vin
--    din secvență (după cele 12), idempotent prin slug.

ALTER TABLE places ADD COLUMN IF NOT EXISTS source_url VARCHAR(300);  -- fișa sursă (visitarad.ro), pentru atribuire

-- 2) cele 12 obiective din V3_1
UPDATE places p SET lat = v.new_lat, lng = v.new_lng
FROM (VALUES
  (1, 'cetatea-aradului', 46.1711, 21.3319, 46.1709, 21.3326),
  (2, 'palatul-cultural', 46.1757, 21.3171, 46.1742, 21.3207),
  (3, 'teatrul-clasic-ioan-slavici', 46.1726, 21.3153, 46.1711, 21.3158),
  (4, 'palatul-administrativ', 46.1768, 21.3145, 46.1754, 21.3193),
  (5, 'biserica-rosie', 46.1740, 21.3160, 46.1774, 21.3202),
  (6, 'catedrala-sfanta-treime', 46.1692, 21.3182, 46.1836, 21.3247),
  (7, 'catedrala-sf-anton', 46.1752, 21.3151, 46.1726, 21.3154),
  (8, 'turnul-de-apa', 46.1792, 21.3118, 46.1697, 21.3080),
  (10, 'lunca-muresului-ceala', 46.1900, 21.2650, 46.1579, 21.2734),
  (11, 'podgoria-minis', 46.1370, 21.6050, 46.1378, 21.6048),
  (12, 'castelul-macea', 46.3860, 21.3167, 46.3844, 21.3104)
) AS v(id, slug, old_lat, old_lng, new_lat, new_lng)
WHERE p.id = v.id AND p.slug = v.slug AND p.lat = v.old_lat AND p.lng = v.old_lng;

